<template>
  <div class="rt">
    <!-- Empty state while running -->
    <div v-if="transcript.length === 0 && isRunning" class="rt-empty">
      <span class="rt-ping" />
      <span class="rt-label rt-label--muted">{{ $t('docnet_initializing_agent') }}</span>
    </div>

    <!-- Entries -->
    <template v-if="transcript.length > 0">
      <div
        v-for="block in visibleBlocks"
        :key="block.id"
        class="rt-entry"
      >
        <!-- Init block -->
        <div v-if="block.type === 'status' && block.statusKind === 'init'" class="rt-row">
          <q-icon name="mdi-play-circle-outline" size="14px" class="rt-icon rt-icon--cyan" />
          <span class="rt-label rt-label--cyan">INIT</span>
          <span v-if="block.model" class="rt-meta">{{ block.model }}</span>
          <span v-if="block.agentName" class="rt-meta">{{ block.agentName }}</span>
        </div>

        <!-- Complete block -->
        <div v-else-if="block.type === 'status' && block.statusKind === 'complete'" class="rt-row">
          <q-icon
            :name="block.success === false ? 'mdi-alert-circle' : 'mdi-check-circle'"
            size="14px"
            :class="block.success === false ? 'rt-icon rt-icon--red' : 'rt-icon rt-icon--emerald'"
          />
          <span class="rt-label" :class="block.success === false ? 'rt-label--red' : 'rt-label--emerald'">
            {{ block.success === false ? 'FAILED' : 'COMPLETED' }}
          </span>
          <span v-if="block.durationMs" class="rt-meta">{{ formatDuration(block.durationMs) }}</span>
          <span v-if="block.tokenCount" class="rt-meta">{{ block.tokenCount.toLocaleString() }} tok</span>
          <span v-if="block.success === false && block.statusText" class="rt-error-inline">{{ block.statusText }}</span>
        </div>

        <!-- Generic status block -->
        <div v-else-if="block.type === 'status'" class="rt-row">
          <q-icon name="mdi-information-outline" size="14px" class="rt-icon rt-icon--muted" />
          <span class="rt-label rt-label--muted">STATUS</span>
          <span class="rt-summary">{{ block.statusText }}</span>
        </div>

        <!-- Message block (STDOUT) -->
        <template v-else-if="block.type === 'message'">
          <div class="rt-row" @click="toggleExpand(block.id)">
            <q-icon name="mdi-console" size="14px" class="rt-icon rt-icon--muted" />
            <span class="rt-label rt-label--muted">STDOUT</span>
            <span class="rt-summary">{{ getMessagePreview(block.content) }}</span>
            <q-icon
              :name="expandedBlocks.has(block.id) ? 'mdi-chevron-up' : 'mdi-chevron-down'"
              size="14px"
              class="rt-chevron"
            />
          </div>
          <div v-if="expandedBlocks.has(block.id)" class="rt-stdout" v-html="renderMarkdown(block.content || '')" />
          <span v-if="isRunning && isLastMessage(block)" class="rt-cursor" />
        </template>

        <!-- Tool call block -->
        <template v-else-if="block.type === 'tool_call'">
          <div class="rt-row" @click="toggleExpand(block.id)">
            <q-icon
              :name="getToolIcon(block.toolCallId)"
              size="14px"
              :class="'rt-icon rt-icon--' + getToolColor(block.toolCallId)"
            />
            <span class="rt-label" :class="'rt-label--' + getToolColor(block.toolCallId)">
              {{ block.toolName }} {{ getToolStatus(block.toolCallId) }}
            </span>
            <span class="rt-summary">{{ getArgsSummary(block) }}</span>
            <q-icon
              :name="expandedBlocks.has(block.id) ? 'mdi-chevron-up' : 'mdi-chevron-down'"
              size="14px"
              class="rt-chevron"
            />
          </div>
          <div v-if="expandedBlocks.has(block.id)" class="rt-detail">
            <div v-if="block.arguments && Object.keys(block.arguments).length > 0">
              <div class="rt-detail__label">{{ $t('docnet_arguments') }}</div>
              <pre class="rt-pre">{{ formatJson(block.arguments) }}</pre>
            </div>
            <div v-if="getToolResult(block.toolCallId)">
              <div class="rt-detail__label">{{ $t('docnet_result') }}</div>
              <pre class="rt-pre" :class="{ 'rt-pre--error': !getToolResult(block.toolCallId)?.success }">{{ formatToolResult(getToolResult(block.toolCallId)) }}</pre>
            </div>
          </div>
        </template>

        <!-- Reasoning block -->
        <div v-else-if="block.type === 'reasoning'" class="rt-row">
          <q-icon name="mdi-brain" size="14px" class="rt-icon rt-icon--purple" />
          <span class="rt-label rt-label--purple">THINKING</span>
          <span class="rt-summary">{{ block.content }}</span>
        </div>

        <!-- Handoff block -->
        <div v-else-if="block.type === 'handoff'" class="rt-row">
          <q-icon name="mdi-swap-horizontal" size="14px" class="rt-icon rt-icon--cyan" />
          <span class="rt-label rt-label--cyan">HANDOFF</span>
          <span class="rt-meta">{{ block.agentName }}</span>
        </div>

        <!-- Error block (STDERR) -->
        <div v-else-if="block.type === 'error'" class="rt-row rt-row--error">
          <q-icon name="mdi-alert-circle" size="14px" class="rt-icon rt-icon--red" />
          <span class="rt-label rt-label--red">STDERR</span>
          <span class="rt-error-text">{{ block.error }}</span>
        </div>
      </div>
    </template>

    <!-- Running indicator at bottom -->
    <div v-if="isRunning && transcript.length > 0 && !hasRecentMessage" class="rt-running">
      <span class="rt-ping" />
      <span class="rt-label rt-label--muted">{{ $t('docnet_processing') }}</span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { TranscriptBlock } from 'src/composables/useRunStream';

const SHORT_RESULT_THRESHOLD = 120;

export default defineComponent({
  name: 'RunTranscript',

  props: {
    transcript: {
      type: Array as PropType<TranscriptBlock[]>,
      required: true,
    },
    isRunning: {
      type: Boolean,
      default: false,
    },
  },

  data() {
    return {
      expandedBlocks: new Set<string>(),
    };
  },

  computed: {
    visibleBlocks(): TranscriptBlock[] {
      return this.transcript.filter((b) => b.type !== 'tool_result');
    },

    toolResults(): Map<string, TranscriptBlock> {
      const map = new Map<string, TranscriptBlock>();
      for (const block of this.transcript) {
        if (block.type === 'tool_result' && block.toolCallId) {
          map.set(block.toolCallId, block);
        }
      }
      return map;
    },

    pendingToolCalls(): Set<string> {
      const calls = new Set<string>();
      for (const block of this.transcript) {
        if (block.type === 'tool_call' && block.toolCallId) {
          calls.add(block.toolCallId);
        }
        if (block.type === 'tool_result' && block.toolCallId) {
          calls.delete(block.toolCallId);
        }
      }
      return calls;
    },

    hasRecentMessage(): boolean {
      const last = this.visibleBlocks[this.visibleBlocks.length - 1];
      return last?.type === 'message';
    },
  },

  methods: {
    toggleExpand(blockId: string) {
      if (this.expandedBlocks.has(blockId)) {
        this.expandedBlocks.delete(blockId);
      } else {
        this.expandedBlocks.add(blockId);
      }
    },

    getToolResult(toolCallId?: string): TranscriptBlock | undefined {
      if (!toolCallId) return undefined;
      return this.toolResults.get(toolCallId);
    },

    isToolPending(toolCallId?: string): boolean {
      if (!toolCallId) return false;
      return this.pendingToolCalls.has(toolCallId);
    },

    getToolIcon(toolCallId?: string): string {
      if (this.isToolPending(toolCallId)) return 'mdi-wrench';
      const result = this.getToolResult(toolCallId);
      if (result?.success === false) return 'mdi-alert-circle';
      if (result) return 'mdi-check';
      return 'mdi-wrench';
    },

    getToolColor(toolCallId?: string): string {
      if (this.isToolPending(toolCallId)) return 'cyan';
      const result = this.getToolResult(toolCallId);
      if (result?.success === false) return 'red';
      if (result) return 'emerald';
      return 'cyan';
    },

    getToolStatus(toolCallId?: string): string {
      if (this.isToolPending(toolCallId)) return 'RUNNING';
      const result = this.getToolResult(toolCallId);
      if (result?.success === false) return 'ERRORED';
      if (result) return 'COMPLETED';
      return 'RUNNING';
    },

    getArgsSummary(block: TranscriptBlock): string {
      if (!block.arguments || typeof block.arguments !== 'object') return '';
      const keys = Object.keys(block.arguments);
      if (keys.length === 0) return '';
      if (keys.length <= 2) return keys.join(', ');
      return `${this.$t('docnet_n_fields', { n: keys.length })} ${keys.slice(0, 3).join(', ')}`;
    },

    getMessagePreview(content?: string): string {
      if (!content) return '';
      const line = content.split('\n')[0];
      return line.length > 80 ? line.slice(0, 80) + '...' : line;
    },

    isLastMessage(block: TranscriptBlock): boolean {
      const messages = this.visibleBlocks.filter((b) => b.type === 'message');
      return messages[messages.length - 1]?.id === block.id;
    },

    isShortResult(toolCallId?: string): boolean {
      if (!toolCallId) return true;
      const result = this.toolResults.get(toolCallId);
      if (!result) return true;
      const text = this.formatToolResult(result);
      return text.length <= SHORT_RESULT_THRESHOLD && !text.includes('\n');
    },

    renderMarkdown(text: string): string {
      return text
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        .replace(/\*(.+?)\*/g, '<em>$1</em>')
        .replace(/`(.+?)`/g, '<code>$1</code>')
        .replace(/\n/g, '<br>');
    },

    formatJson(obj: Record<string, any>): string {
      try {
        const str = JSON.stringify(obj, null, 2);
        return str.length > 2000 ? str.slice(0, 2000) + '\n...' : str;
      } catch {
        return String(obj);
      }
    },

    formatToolResult(block?: TranscriptBlock): string {
      if (!block) return '';
      if (block.error) return block.error;
      if (block.result === undefined || block.result === null) return 'OK';
      if (typeof block.result === 'string') {
        return block.result.length > 2000 ? block.result.slice(0, 2000) + '...' : block.result;
      }
      return this.formatJson(block.result);
    },

    formatDuration(ms: number): string {
      if (ms < 1000) return `${ms}ms`;
      const secs = Math.round(ms / 1000);
      if (secs < 60) return `${secs}s`;
      const mins = Math.floor(secs / 60);
      const remainSecs = secs % 60;
      return `${mins}m ${remainSecs}s`;
    },
  },
});
</script>

