<template>
  <div class="docnet-run-detail">
    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Not found -->
    <div v-else-if="!run" class="text-center q-pa-xl">
      <q-icon name="search_off" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6">{{ $t('run_not_found') }}</p>
      <f-btn appearance="flat" :label="$t('back_to_issue')" icon="arrow_back" @click="goBack" />
    </div>

    <!-- Run detail -->
    <div v-else>
      <!-- Header -->
      <div class="run-detail-header">
        <div class="run-detail-header__left">
          <f-btn appearance="flat" icon="arrow_back" dense @click="goBack" />
          <div>
            <h2 class="run-detail-header__title">{{ run.agent_name }}</h2>
            <span class="run-detail-header__id">{{ $t('docnet_run_label') }} {{ run.id }}</span>
          </div>
        </div>
        <div class="run-detail-header__right">
          <q-badge
            :color="statusColor"
            text-color="white"
            class="run-detail-header__status"
          >
            {{ run.status }}
          </q-badge>
        </div>
      </div>

      <!-- Metadata -->
      <div class="run-detail-meta q-mb-md">
        <div class="run-detail-meta__item">
          <span class="text-caption text-grey-6">{{ $t('started') }}</span>
          <span class="text-body2">{{ formatDate(run.started_at) }}</span>
        </div>
        <div v-if="run.completed_at" class="run-detail-meta__item">
          <span class="text-caption text-grey-6">{{ $t('completed') }}</span>
          <span class="text-body2">{{ formatDate(run.completed_at) }}</span>
        </div>
        <div v-if="run.duration_ms" class="run-detail-meta__item">
          <span class="text-caption text-grey-6">{{ $t('duration') }}</span>
          <span class="text-body2">{{ formatDuration(run.duration_ms) }}</span>
        </div>
        <div v-if="run.token_usage" class="run-detail-meta__item">
          <span class="text-caption text-grey-6">{{ $t('tokens') }}</span>
          <span class="text-body2">{{ run.token_usage.billed != null ? run.token_usage.billed.toLocaleString() : '—' }}</span>
        </div>
      </div>

      <!-- Result text -->
      <div v-if="run.result_text" class="detail-card q-mb-md q-pa-md">
        <div class="section-label q-mb-sm">{{ $t('result') }}</div>
        <p class="text-body2" style="white-space: pre-wrap;">{{ run.result_text }}</p>
      </div>

      <!-- Error -->
      <div v-if="run.error" class="detail-card q-mb-md q-pa-md" style="border-left: 3px solid #ef5350;">
        <div class="section-label text-negative q-mb-sm">{{ $t('error') }}</div>
        <p class="text-body2 text-negative">{{ run.error }}</p>
      </div>

      <!-- Transcript -->
      <div class="detail-card q-pa-md">
        <div class="section-label q-mb-sm">{{ $t('transcript') }} ({{ $t('docnet_events_count', { n: run.events.length }) }})</div>
        <RunTranscript :transcript="transcript" :is-running="isRunning" />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { DocNetAgentRun, DocNetRunEvent, DocNetRunStatus } from 'src/@types/docnet';
import type { TranscriptBlock } from 'src/composables/useRunStream';
import type { DocNetWsEvent } from 'src/store/DocNet/docnet-websocket.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import DocNetIssueService from 'src/services/docnet/DocNetIssueService';
import RunTranscript from './components/RunTranscript.vue';

const POLL_INTERVAL_MS = 3_000;

export default defineComponent({
  name: 'DocNetRunDetail',

  components: { RunTranscript },

  data() {
    return {
      run: null as DocNetAgentRun | null,
      loading: false,
      transcript: [] as TranscriptBlock[],
      streamRunId: null as string | null,
      streamAgentName: null as string | null,
      streamRunStatus: null as DocNetRunStatus | null,
      wsConnected: false,
      messageBuffer: '',
      blockCounter: 0,
      lastEventIndex: 0,
      wsUnsubscribe: null as (() => void) | null,
      pollTimer: null as ReturnType<typeof setInterval> | null,
      issueService: new DocNetIssueService(),
    };
  },

  computed: {
    statusColor(): string {
      const map: Record<string, string> = {
        succeeded: 'positive',
        failed: 'negative',
        stopped: 'warning',
        running: 'blue',
        queued: 'grey',
      };
      return map[this.run?.status || ''] || 'grey';
    },

    isRunning(): boolean {
      return this.streamRunStatus === 'running' || this.streamRunStatus === 'queued';
    },
  },

  async mounted() {
    const issueId = this.$route.params.id as string;
    const runId = this.$route.params.runId as string;

    if (issueId && runId) {
      this.loading = true;
      try {
        this.run = await this.issueService.getRun(issueId, runId);
        if (this.run) {
          this.loadFromEvents(this.run.events, this.run.status);
          if (this.run.status === 'running') {
            this.startStream(issueId, runId);
          }
        }
      } catch {
        this.run = null;
      } finally {
        this.loading = false;
      }
    }
  },

  beforeUnmount() {
    this.stopStream();
  },

  methods: {
    // ─── Transcript building ───────────────────────────────────────

    nextBlockId(): string {
      return `block-${++this.blockCounter}`;
    },

    addBlock(block: Omit<TranscriptBlock, 'id'>): void {
      this.transcript.push({ ...block, id: this.nextBlockId() });
    },

    handleStreamEvent(event: { type?: string; data?: Record<string, any> }): void {
      const ts = new Date().toISOString();
      const type = event.type || '';

      switch (type) {
        case 'agent_start':
          this.streamRunStatus = 'running';
          this.streamAgentName = event.data?.agent_name || null;
          this.addBlock({
            type: 'status',
            timestamp: ts,
            statusKind: 'init',
            statusText: this.$t('docnet_agent_started', { name: event.data?.agent_name || this.$t('docnet_unknown') }),
            agentName: event.data?.agent_name,
            model: event.data?.model,
          });
          break;

        case 'agent_chunk':
          if (event.data?.content) {
            this.messageBuffer += event.data.content;
            const lastBlock = this.transcript[this.transcript.length - 1];
            if (lastBlock && lastBlock.type === 'message') {
              lastBlock.content = this.messageBuffer;
            } else {
              this.addBlock({
                type: 'message',
                timestamp: ts,
                content: this.messageBuffer,
              });
            }
          }
          if (event.data?.is_final) {
            this.messageBuffer = '';
          }
          break;

        case 'agent_tool_call':
          if (this.messageBuffer) {
            this.messageBuffer = '';
          }
          this.addBlock({
            type: 'tool_call',
            timestamp: ts,
            toolName: event.data?.tool_name,
            toolCallId: event.data?.tool_call_id,
            arguments: event.data?.arguments,
          });
          break;

        case 'agent_tool_result':
          this.addBlock({
            type: 'tool_result',
            timestamp: ts,
            toolName: event.data?.tool_name,
            toolCallId: event.data?.tool_call_id,
            success: event.data?.success,
            result: event.data?.result,
            error: event.data?.error,
          });
          break;

        case 'agent_complete':
          this.streamRunStatus = event.data?.success ? 'succeeded' : 'failed';
          this.messageBuffer = '';
          this.addBlock({
            type: 'status',
            timestamp: ts,
            statusKind: 'complete',
            statusText: event.data?.success
              ? this.$t('docnet_completed_in', { n: Math.round((event.data?.execution_time_ms || 0) / 1000) })
              : this.$t('docnet_failed_with_error', { error: event.data?.error || this.$t('docnet_unknown_error') }),
            durationMs: event.data?.execution_time_ms,
            tokenCount: event.data?.token_count,
            success: event.data?.success,
          });
          this.stopStream();
          break;

        case 'agent_reasoning':
          this.addBlock({
            type: 'reasoning',
            timestamp: ts,
            content: event.data?.content || this.$t('docnet_thinking'),
          });
          break;

        case 'agent_handoff':
          this.addBlock({
            type: 'handoff',
            timestamp: ts,
            agentName: event.data?.new_agent_name,
            statusText: this.$t('docnet_handed_off_to', { agent: event.data?.new_agent_name || this.$t('docnet_agent_generic') }),
          });
          break;

        case 'lifecycle':
          if (event.data?.name === 'run_started') {
            this.addBlock({
              type: 'status',
              timestamp: ts,
              statusKind: 'init',
              statusText: this.$t('docnet_agent_initializing', { name: event.data?.agent_name || '' }),
              agentName: event.data?.agent_name,
            });
          }
          break;

        case 'agent_error':
        case 'error':
          this.addBlock({
            type: 'error',
            timestamp: ts,
            error: event.data?.error_message || event.data?.error || this.$t('docnet_unknown_error'),
          });
          if (event.data?.recoverable === false) {
            this.streamRunStatus = 'failed';
            this.stopStream();
          }
          break;
      }
    },

    loadFromEvents(events: DocNetRunEvent[], status: DocNetRunStatus): void {
      this.transcript = [];
      this.messageBuffer = '';
      this.blockCounter = 0;
      this.streamRunStatus = status;
      for (const evt of events) {
        this.handleStreamEvent({ type: evt.type, data: evt.data });
      }
      this.messageBuffer = '';
    },

    // ─── WebSocket channel ─────────────────────────────────────────

    connectChannel(issueId: string): void {
      if (this.wsUnsubscribe) return;

      const wsStore = useDocNetWebSocketStore();
      this.wsConnected = wsStore.connected;

      this.wsUnsubscribe = wsStore.onIssueEvent(issueId, (msg: DocNetWsEvent) => {
        this.wsConnected = true;
        this.handleStreamEvent({ type: msg.type, data: msg.data as Record<string, any> });
        this.lastEventIndex++;
      });
    },

    disconnectChannel(): void {
      if (this.wsUnsubscribe) {
        this.wsUnsubscribe();
        this.wsUnsubscribe = null;
      }
      this.wsConnected = false;
    },

    // ─── Polling fallback ──────────────────────────────────────────

    startPolling(issueId: string, runId: string): void {
      if (this.pollTimer) return;
      this.pollTimer = setInterval(async () => {
        try {
          const run = await this.issueService.getRun(issueId, runId);

          if (run.agent_name) {
            this.streamAgentName = run.agent_name;
          }

          if (run.events && run.events.length > this.lastEventIndex) {
            const newEvents = run.events.slice(this.lastEventIndex);
            for (const evt of newEvents) {
              this.handleStreamEvent({ type: evt.type, data: evt.data });
            }
            this.lastEventIndex = run.events.length;
          }

          if (run.status !== 'running' && run.status !== 'queued') {
            if (!run.events || run.events.length === 0) {
              const ts = new Date().toISOString();
              if (run.status === 'failed') {
                this.addBlock({ type: 'error', timestamp: ts, error: run.error || this.$t('docnet_agent_run_failed') });
              } else if (run.result_text) {
                this.addBlock({ type: 'message', timestamp: ts, content: run.result_text });
              }
              this.streamRunStatus = run.status;
              this.addBlock({
                type: 'status',
                timestamp: ts,
                statusText: run.status === 'succeeded'
                  ? this.$t('docnet_completed_in', { n: Math.round((run.duration_ms || 0) / 1000) })
                  : this.$t('docnet_run_status', { status: run.status }),
              });
            } else {
              this.streamRunStatus = run.status;
            }

            this.disconnectChannel();
            this.stopPolling();
          }
        } catch {
          // polling failure is non-critical
        }
      }, POLL_INTERVAL_MS);
    },

    stopPolling(): void {
      if (this.pollTimer) {
        clearInterval(this.pollTimer);
        this.pollTimer = null;
      }
    },

    // ─── Stream lifecycle ──────────────────────────────────────────

    startStream(issueId: string, runId: string): void {
      this.streamRunId = runId;
      this.streamRunStatus = 'running';
      this.transcript = [];
      this.messageBuffer = '';
      this.blockCounter = 0;
      this.lastEventIndex = 0;
      this.connectChannel(issueId);
      this.startPolling(issueId, runId);
    },

    stopStream(): void {
      this.disconnectChannel();
      this.stopPolling();
    },

    // ─── Navigation / formatting ───────────────────────────────────

    goBack(): void {
      const issueId = this.$route.params.id as string;
      this.$router.push(`/doc-net/issues/${issueId}`);
    },

    formatDate(iso: string): string {
      return new Date(iso).toLocaleString(undefined, {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    },

    formatDuration(ms: number): string {
      if (ms < 1000) return `${ms}ms`;
      const secs = Math.round(ms / 1000);
      if (secs < 60) return `${secs}s`;
      const mins = Math.floor(secs / 60);
      const remainSecs = secs % 60;
      return `${mins}m ${remainSecs}s`;
    },
  },
});
</script>

